#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    getline(cin, s);
    auto isAtStart3 = [&](const string& str) { return str.size() >= 3 && str.substr(0,3) == "dot"; };
    auto isAtStart2 = [&](const string& str) { return str.size() >= 2 && str.substr(0,2) == "at"; };
    auto endsWith3 = [&](const string& str) { return str.size() >= 3 && str.substr(str.size()-3) == "dot"; };
    auto endsWith2 = [&](const string& str) { return str.size() >= 2 && str.substr(str.size()-2) == "at"; };

    bool condition = false;
    if (isAtStart3(s) || isAtStart2(s) || (s.size() >= 2 && s.substr(s.size()-2) == "at") || (s.size() >=3 && s.substr(s.size()-3) == "dot")) {
        condition = true;
    }

    if (condition) {
        // Helper lambda to process starting with 'dot'
        auto processDotPrefix = [&](string s_in) {
            string t = s_in.substr(3);
            vector<string> a;
            size_t start = 0, end;
            while ((end = t.find("dot", start)) != string::npos) {
                a.push_back(t.substr(start, end - start));
                start = end + 3;
            }
            a.push_back(t.substr(start));
            string l = "";
            for (size_t i = 0; i < a.size(); ++i) {
                l += a[i];
                if (i != a.size() -1) l += ".";
            }
            size_t b = l.find("at");
            string o = l.substr(0, b) + "@" + l.substr(b+2);
            string q = "dot" + o;
            if (!q.empty()) {
                if (q.back() == '.') {
                    q = q.substr(0, q.size() -1);
                    return q + "dot";
                } else if (q.back() == '@') {
                    q = q.substr(0, q.size() -1);
                    return q + "at";
                } else {
                    return q;
                }
            }
            return q;
        };

        // Helper lambda to process starting with 'at'
        auto processAtPrefix = [&](string s_in) {
            string t = s_in.substr(2);
            vector<string> a;
            size_t start = 0, end;
            while ((end = t.find("dot", start)) != string::npos) {
                a.push_back(t.substr(start, end - start));
                start = end + 3;
            }
            a.push_back(t.substr(start));
            string l = "";
            for (size_t i = 0; i < a.size(); ++i) {
                l += a[i];
                if (i != a.size() -1) l += ".";
            }
            size_t b = l.find("at");
            string o = l.substr(0, b) + "@" + l.substr(b+2);
            string q = "at" + o;
            if (!q.empty()) {
                if (q.back() == '.') {
                    q = q.substr(0, q.size() -1);
                    return q + "dot";
                } else if (q.back() == '@') {
                    q = q.substr(0, q.size() -1);
                    return q + "at";
                } else {
                    return q;
                }
            }
            return q;
        };

        // Process cases where s starts with 'dot'
        if (isAtStart3(s)) {
            s = processDotPrefix(s);
        }

        // Process cases where s starts with 'at'
        if (isAtStart2(s)) {
            s = processAtPrefix(s);
        }

        // Process case where ends with 'dot' and doesn't start with 'dot' or 'at'
        if (s.size() >=3 && s.substr(s.size()-3) == "dot" && !isAtStart3(s) && !isAtStart2(s)) {
            string t = s.substr(0, s.size() -3);
            vector<string> a;
            size_t start = 0, end;
            while ((end = t.find("dot", start)) != string::npos) {
                a.push_back(t.substr(start, end - start));
                start = end + 3;
            }
            a.push_back(t.substr(start));
            string l = "";
            for (size_t i = 0; i < a.size(); ++i) {
                l += a[i];
                if (i != a.size() -1) l += ".";
            }
            size_t b = l.find("at");
            string o = l.substr(0, b) + "@" + l.substr(b+2);
            s = o + "dot";
        }

        // Process case where ends with 'at' and doesn't start with 'dot' or 'at'
        if (s.size() >=2 && s.substr(s.size()-2) == "at" && !isAtStart2(s) && !isAtStart3(s)) {
            string t = s.substr(0, s.size() -2);
            vector<string> a;
            size_t start = 0, end;
            while ((end = t.find("dot", start)) != string::npos) {
                a.push_back(t.substr(start, end - start));
                start = end + 3;
            }
            a.push_back(t.substr(start));
            string l = "";
            for (size_t i = 0; i < a.size(); ++i) {
                l += a[i];
                if (i != a.size() -1) l += ".";
            }
            size_t b = l.find("at");
            string o = l.substr(0, b) + "@" + l.substr(b+2);
            s = o + "at";
        }

        cout << s << "\n";

    } else {
        // No special prefix or suffix
        vector<string> a;
        size_t start = 0, end;
        while ((end = s.find("dot", start)) != string::npos) {
            a.push_back(s.substr(start, end - start));
            start = end + 3;
        }
        a.push_back(s.substr(start));
        string l = "";
        for (size_t i = 0; i < a.size(); ++i) {
            l += a[i];
            if (i != a.size() -1) l += ".";
        }
        size_t b = l.find("at");
        string q = l;
        if (b != string::npos) {
            q = l.substr(0, b) + "@" + l.substr(b+2);
        }
        cout << q << "\n";
    }
    return 0;
}
